function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-V55R98E3BL');

head.b:skin:
:root {
  --nabd-navy-dark: #0A192F;
  --nabd-navy-primary: #0D2040;
  --nabd-navy-light: #1B2B6B;
  --nabd-navy-surface: #243B80;
  --nabd-gold: #D4AF37;
  --nabd-gold-light: #F59E0B;
  --nabd-emerald: #10B981;
  --nabd-emerald-dark: #059669;
  --nabd-bg: #F8FAFC;
  --nabd-card-bg: #FFFFFF;
  --nabd-text-main: #0F172A;
  --nabd-text-muted: #64748B;
  --nabd-border: #E2E8F0;
  --nabd-shadow: 0 4px 15px -2px rgba(13, 32, 64, 0.07);
  --nabd-shadow-lg: 0 12px 25px -4px rgba(13, 32, 64, 0.12);
  --nabd-radius: 16px;
  --safe-bottom: env(safe-area-inset-bottom, 15px);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  font-family: 'Cairo', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--nabd-bg);
  color: var(--nabd-text-main);
  direction: rtl;
  text-align: right;
  line-height: 1.8;
  overflow-x: hidden;
  word-wrap: break-word;
  padding-bottom: 75px; /* Space for mobile floating bar */
}

a {
  color: inherit;
  text-decoration: none;
  transition: all 0.2s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 14px;
}

/* Reading Progress Bar */
#reading-progress {
  position: fixed;
  top: 0;
  right: 0;
  height: 3.5px;
  background: linear-gradient(90deg, var(--nabd-gold), var(--nabd-emerald));
  width: 0%;
  z-index: 99999;
  transition: width 0.1s ease;
}

/* ── Mobile-Optimized Header & App Bar ── */
.main-header {
  background: linear-gradient(135deg, var(--nabd-navy-dark) 0%, var(--nabd-navy-primary) 100%);
  color: #FFFFFF;
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 4px 15px rgba(10, 25, 47, 0.2);
  border-bottom: 2px solid var(--nabd-gold);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  gap: 10px;
}
.brand-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.logo-img-wrapper {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  overflow: hidden;
  background: #FFFFFF;
  padding: 2px;
  border: 2px solid var(--nabd-gold);
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0,0,0,0.2);
}
.logo-img-wrapper img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.brand-title-group {
  min-width: 0;
}
.brand-title-group h1, .brand-title-group .site-title {
  font-size: 15px;
  font-weight: 900;
  color: #FFFFFF;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.brand-title-group p {
  font-size: 10.5px;
  color: var(--nabd-gold);
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.btn-header-call {
  background: rgba(212, 175, 55, 0.18);
  border: 1px solid var(--nabd-gold);
  color: var(--nabd-gold) !important;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.btn-book-nav {
  background: linear-gradient(135deg, var(--nabd-gold) 0%, var(--nabd-gold-light) 100%);
  color: var(--nabd-navy-dark) !important;
  padding: 6px 14px;
  border-radius: 10px;
  font-weight: 900;
  font-size: 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 3px 10px rgba(212, 175, 55, 0.35);
}
.mobile-menu-toggle {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #FFFFFF;
  font-size: 16px;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

/* Desktop Nav Links (Hidden on Mobile) */
.desktop-nav-links {
  display: none;
  align-items: center;
  gap: 4px;
  list-style: none;
}
.desktop-nav-links a {
  color: #F1F5F9;
  font-weight: 700;
  font-size: 13px;
  padding: 7px 12px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.desktop-nav-links a:hover, .desktop-nav-links a.active {
  background: rgba(255, 255, 255, 0.12);
  color: var(--nabd-gold);
}
@media (min-width: 992px) {
  .desktop-nav-links { display: flex; }
  .mobile-menu-toggle { display: none; }
  .btn-header-call { display: none; }
  .brand-title-group h1, .brand-title-group .site-title { font-size: 18px; }
  .brand-title-group p { font-size: 12px; }
  .logo-img-wrapper { width: 48px; height: 48px; }
  body { padding-bottom: 0; }
}

/* ── Mobile Slide Drawer ── */
.drawer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(10, 25, 47, 0.7);
  backdrop-filter: blur(4px);
  z-index: 9998;
  display: none;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.drawer-overlay.open {
  display: block;
  opacity: 1;
}
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -300px;
  width: 290px;
  height: 100%;
  background: var(--nabd-navy-dark);
  z-index: 9999;
  box-shadow: -5px 0 25px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  overflow-y: auto;
  padding: 20px 16px;
}
.mobile-drawer.open {
  right: 0;
}
.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 16px;
}
.drawer-close-btn {
  background: rgba(255, 255, 255, 0.1);
  border: none;
  color: #FFFFFF;
  font-size: 18px;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  cursor: pointer;
}
.drawer-menu-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.drawer-menu-list a {
  color: #FFFFFF;
  font-weight: 700;
  font-size: 13.5px;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid rgba(255, 255, 255, 0.05);
}
.drawer-menu-list a:hover {
  background: rgba(212, 175, 55, 0.15);
  border-color: var(--nabd-gold);
  color: var(--nabd-gold);
}
.drawer-menu-list a i {
  color: var(--nabd-gold);
}
.drawer-footer-card {
  margin-top: auto;
  padding-top: 20px;
}
.drawer-call-btn {
  background: linear-gradient(135deg, #10B981, #059669);
  color: #FFFFFF !important;
  text-align: center;
  padding: 11px;
  border-radius: 12px;
  font-weight: 800;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

/* ── Mobile-First Hero Card ── */
.hero-banner {
  background: linear-gradient(135deg, var(--nabd-navy-dark) 0%, var(--nabd-navy-primary) 60%, var(--nabd-navy-light) 100%);
  color: #FFFFFF;
  padding: 20px 0;
  position: relative;
  overflow: hidden;
  border-bottom: 2px solid var(--nabd-gold);
}
.hero-inner {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(212, 175, 55, 0.18);
  border: 1px solid var(--nabd-gold);
  color: var(--nabd-gold);
  padding: 3px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 800;
  margin-bottom: 8px;
}
.hero-text h2 {
  font-size: 19px;
  font-weight: 900;
  line-height: 1.35;
  margin-bottom: 8px;
  color: #FFFFFF;
}
.hero-text h2 span {
  color: var(--nabd-gold);
}
.hero-text p {
  font-size: 12.5px;
  color: #E2E8F0;
  margin-bottom: 14px;
  line-height: 1.65;
}

/* Mobile Poster Card */
.hero-poster-card {
  width: 100%;
  max-width: 320px;
  margin: 0 auto;
  border-radius: 16px;
  overflow: hidden;
  border: 2px solid var(--nabd-gold);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
  background: #000;
}
.hero-poster-card img {
  width: 100%;
  height: auto;
  object-fit: cover;
  display: block;
}

.hero-btns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.btn-hero-primary {
  background: linear-gradient(135deg, var(--nabd-emerald) 0%, var(--nabd-emerald-dark) 100%);
  color: #FFFFFF !important;
  padding: 10px 12px;
  border-radius: 10px;
  font-weight: 800;
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  text-align: center;
  box-shadow: 0 3px 10px rgba(16, 185, 129, 0.3);
}
.btn-hero-secondary {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #FFFFFF !important;
  padding: 10px 12px;
  border-radius: 10px;
  font-weight: 800;
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  text-align: center;
}

@media (min-width: 768px) {
  .hero-banner { padding: 32px 0; }
  .hero-inner { flex-direction: row; align-items: center; justify-content: space-between; gap: 24px; }
  .hero-text { max-width: 580px; }
  .hero-text h2 { font-size: 25px; }
  .hero-text p { font-size: 14px; }
  .hero-poster-card { width: 280px; margin: 0; }
  .hero-btns { display: flex; }
  .btn-hero-primary, .btn-hero-secondary { width: auto; padding: 10px 20px; font-size: 13px; }
}

/* ── Mobile Categories Bar & Search ── */
.categories-bar {
  background: #FFFFFF;
  padding: 10px 0;
  border-bottom: 1px solid var(--nabd-border);
  box-shadow: 0 2px 6px rgba(0,0,0,0.02);
  position: sticky;
  top: 58px;
  z-index: 900;
}
.categories-wrapper {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.categories-list {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 2px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.categories-list::-webkit-scrollbar { display: none; }

.cat-pill {
  background: #F1F5F9;
  color: var(--nabd-navy-primary);
  padding: 5px 12px;
  border-radius: 20px;
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
  border: 1px solid #E2E8F0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}
.cat-pill:hover, .cat-pill.active {
  background: var(--nabd-navy-primary);
  color: #FFFFFF;
  border-color: var(--nabd-gold);
}
.cat-pill i {
  color: var(--nabd-gold);
  font-size: 11px;
}

.blog-search-form {
  display: flex;
  align-items: center;
  background: #F1F5F9;
  border: 1px solid #CBD5E1;
  border-radius: 20px;
  padding: 3px 10px;
  width: 100%;
}
.blog-search-form input {
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  color: var(--nabd-navy-primary);
  outline: none;
  padding: 4px;
  width: 100%;
}
.blog-search-form button {
  border: none;
  background: transparent;
  color: var(--nabd-navy-light);
  cursor: pointer;
  font-size: 13px;
  padding: 4px;
}

@media (min-width: 768px) {
  .categories-wrapper {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
  .blog-search-form {
    width: 250px;
  }
}

/* ── Main Layout Grid ── */
.main-wrapper {
  padding: 20px 0 40px 0;
}
.layout-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 992px) {
  .layout-grid {
    grid-template-columns: 1fr 320px;
    gap: 28px;
  }
}

/* Section Title */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  border-bottom: 2px solid #E2E8F0;
  padding-bottom: 8px;
  position: relative;
}
.section-header::after {
  content: '';
  position: absolute;
  bottom: -2px;
  right: 0;
  width: 60px;
  height: 2px;
  background: var(--nabd-gold);
}
.section-title {
  font-size: 16px;
  font-weight: 900;
  color: var(--nabd-navy-primary);
  display: flex;
  align-items: center;
  gap: 6px;
}
.section-title i {
  color: var(--nabd-gold);
}

/* ── Mobile-Optimized Post Cards Grid ── */
.posts-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}
@media (min-width: 640px) {
  .posts-grid {
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  }
}

.nabd-post-card {
  background: var(--nabd-card-bg);
  border-radius: var(--nabd-radius);
  border: 1px solid var(--nabd-border);
  overflow: hidden;
  box-shadow: var(--nabd-shadow);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.nabd-post-card:active {
  transform: scale(0.99);
}
.post-thumb-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: linear-gradient(135deg, var(--nabd-navy-primary) 0%, var(--nabd-navy-surface) 100%);
  overflow: hidden;
}
.post-thumb-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.post-category-tag {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(13, 32, 64, 0.9);
  color: var(--nabd-gold);
  border: 1px solid rgba(212, 175, 55, 0.4);
  padding: 3px 9px;
  border-radius: 14px;
  font-size: 10.5px;
  font-weight: 800;
  backdrop-filter: blur(4px);
}
.post-body {
  padding: 14px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.post-meta-top {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  color: var(--nabd-text-muted);
  margin-bottom: 6px;
}
.post-meta-top span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.post-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--nabd-navy-primary);
  line-height: 1.45;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.post-snippet {
  font-size: 12px;
  color: var(--nabd-text-muted);
  line-height: 1.6;
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  flex-grow: 1;
}
.post-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #F1F5F9;
  padding-top: 10px;
  margin-top: auto;
}
.read-more-btn {
  color: var(--nabd-navy-primary);
  font-size: 12px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.post-author-name {
  font-size: 10.5px;
  color: var(--nabd-text-muted);
  font-weight: 700;
}

/* ── Mobile Single Article Reading View ── */
.single-post-wrapper {
  background: var(--nabd-card-bg);
  border-radius: var(--nabd-radius);
  border: 1px solid var(--nabd-border);
  padding: 18px 14px;
  box-shadow: var(--nabd-shadow);
  margin-bottom: 24px;
}
@media (min-width: 768px) {
  .single-post-wrapper { padding: 28px; }
}
.single-post-header {
  border-bottom: 2px solid #F1F5F9;
  padding-bottom: 14px;
  margin-bottom: 18px;
}
.single-post-badge {
  display: inline-block;
  background: rgba(13, 32, 64, 0.08);
  color: var(--nabd-navy-primary);
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 800;
  margin-bottom: 8px;
  border: 1px solid rgba(13, 32, 64, 0.15);
}
.single-post-title {
  font-size: 20px;
  font-weight: 900;
  color: var(--nabd-navy-primary);
  line-height: 1.4;
  margin-bottom: 10px;
}
@media (min-width: 768px) {
  .single-post-title { font-size: 24px; }
}
.single-post-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 11px;
  color: var(--nabd-text-muted);
  font-weight: 600;
}
.single-post-meta span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.single-post-body {
  font-size: 15.5px;
  line-height: 1.95;
  color: #1E293B;
}
.single-post-body h2 {
  font-size: 18px;
  font-weight: 900;
  color: var(--nabd-navy-primary);
  margin: 24px 0 10px 0;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--nabd-gold);
  display: inline-block;
}
.single-post-body h3 {
  font-size: 16px;
  font-weight: 800;
  color: var(--nabd-navy-light);
  margin: 18px 0 8px 0;
}
.single-post-body p {
  margin-bottom: 14px;
}
.single-post-body ul, .single-post-body ol {
  margin: 12px 18px 16px 0;
  line-height: 1.8;
}
.single-post-body li {
  margin-bottom: 6px;
}
.single-post-body blockquote {
  background: #F8FAFC;
  border-right: 4px solid var(--nabd-gold);
  padding: 12px 16px;
  border-radius: 0 10px 10px 0;
  margin: 16px 0;
  font-style: italic;
  color: var(--nabd-navy-primary);
  font-weight: 700;
}

/* In-Article Clinical CTA */
.post-clinical-cta {
  background: linear-gradient(135deg, var(--nabd-navy-primary) 0%, var(--nabd-navy-light) 100%);
  color: #FFFFFF;
  padding: 18px;
  border-radius: 16px;
  margin: 24px 0;
  border: 2px solid var(--nabd-gold);
  box-shadow: var(--nabd-shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: center;
}
.post-clinical-cta-text h4 {
  font-size: 15px;
  font-weight: 900;
  color: #FFFFFF;
  margin-bottom: 4px;
}
.post-clinical-cta-text p {
  font-size: 12px;
  color: #CBD5E1;
  margin: 0;
}
.post-clinical-cta-btns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

/* Post Share Bar */
.post-share-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  background: #F8FAFC;
  border: 1px solid var(--nabd-border);
  padding: 10px 14px;
  border-radius: 12px;
  margin: 20px 0;
}
.share-title {
  font-size: 12px;
  font-weight: 800;
  color: var(--nabd-navy-primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.share-buttons {
  display: flex;
  gap: 6px;
}
.share-btn {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 14px;
  border: none;
}
.share-wa { background: #25D366; }
.share-fb { background: #1877F2; }
.share-tg { background: #0088CC; }
.share-copy { background: var(--nabd-navy-primary); cursor: pointer; }

/* Author Signature Box */
.author-box {
  background: #F8FAFC;
  border: 1px solid var(--nabd-border);
  border-radius: var(--nabd-radius);
  padding: 14px;
  margin: 20px 0;
  display: flex;
  align-items: center;
  gap: 12px;
}
.author-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  overflow: hidden;
  background: #FFFFFF;
  border: 2px solid var(--nabd-gold);
  flex-shrink: 0;
}
.author-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.author-info h5 {
  font-size: 13.5px;
  font-weight: 900;
  color: var(--nabd-navy-primary);
  margin-bottom: 2px;
}
.author-info p {
  font-size: 11.5px;
  color: var(--nabd-text-muted);
  margin: 0;
  line-height: 1.5;
}

/* ── Sidebar & Mobile Cards ── */
.sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.sidebar-widget {
  background: var(--nabd-card-bg);
  border-radius: var(--nabd-radius);
  border: 1px solid var(--nabd-border);
  padding: 16px;
  box-shadow: var(--nabd-shadow);
}
.widget-title {
  font-size: 14px;
  font-weight: 900;
  color: var(--nabd-navy-primary);
  margin-bottom: 12px;
  padding-bottom: 6px;
  border-bottom: 2px solid #F1F5F9;
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
}
.widget-title::after {
  content: '';
  position: absolute;
  bottom: -2px;
  right: 0;
  width: 35px;
  height: 2px;
  background: var(--nabd-gold);
}
.widget-title i {
  color: var(--nabd-gold);
}

.supervisor-widget {
  background: linear-gradient(135deg, #0A192F 0%, #1B2B6B 100%);
  color: #FFFFFF;
  border: 2px solid var(--nabd-gold);
  text-align: center;
}
.supervisor-widget .widget-title {
  color: #FFFFFF;
  border-color: rgba(255, 255, 255, 0.2);
  justify-content: center;
}
.supervisor-widget .widget-title::after {
  right: calc(50% - 18px);
}
.supervisor-img-wrap {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  overflow: hidden;
  margin: 0 auto 10px auto;
  border: 3px solid var(--nabd-gold);
}
.supervisor-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.supervisor-name {
  font-size: 15px;
  font-weight: 900;
  color: #FFFFFF;
  margin-bottom: 2px;
}
.supervisor-title {
  font-size: 11.5px;
  color: var(--nabd-gold);
  font-weight: 700;
  margin-bottom: 8px;
}

.emergency-widget {
  background: linear-gradient(135deg, #7F1D1D 0%, #991B1B 100%);
  color: #FFFFFF;
  border: 2px solid #EF4444;
}
.emergency-widget .widget-title {
  color: #FFFFFF;
  border-color: rgba(255, 255, 255, 0.2);
}
.emergency-widget .widget-title::after {
  background: #FCA5A5;
}
.emergency-call-btn {
  background: #FFFFFF;
  color: #991B1B !important;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px;
  border-radius: 10px;
  font-weight: 900;
  font-size: 13px;
  margin-top: 10px;
}

.sidebar-links-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sidebar-links-list li a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  background: #F8FAFC;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  color: var(--nabd-navy-primary);
  border: 1px solid #E2E8F0;
}

/* ── Mobile Sticky Bottom Action Bar ── */
.mobile-bottom-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(10, 25, 47, 0.95);
  backdrop-filter: blur(10px);
  border-top: 2px solid var(--nabd-gold);
  padding: 8px 12px var(--safe-bottom) 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  z-index: 9990;
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.25);
}
@media (min-width: 992px) {
  .mobile-bottom-bar { display: none; }
}
.bar-btn-wa {
  background: #25D366;
  color: #FFFFFF !important;
  flex: 1;
  padding: 9px 8px;
  border-radius: 10px;
  font-weight: 900;
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
}
.bar-btn-call {
  background: var(--nabd-gold);
  color: var(--nabd-navy-dark) !important;
  width: 44px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}
.bar-btn-book {
  background: var(--nabd-navy-surface);
  color: #FFFFFF !important;
  border: 1px solid var(--nabd-gold);
  flex: 1;
  padding: 9px 8px;
  border-radius: 10px;
  font-weight: 900;
  font-size: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
}

/* ── Footer ── */
.main-footer {
  background: var(--nabd-navy-dark);
  color: #FFFFFF;
  padding: 30px 0 20px 0;
  border-top: 3px solid var(--nabd-gold);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  margin-bottom: 24px;
}
@media (min-width: 768px) {
  .footer-grid { grid-template-columns: 2fr 1fr 1.5fr; gap: 24px; }
}
.footer-brand h3 {
  font-size: 16px;
  font-weight: 900;
  color: #FFFFFF;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.footer-brand p {
  font-size: 12px;
  color: #CBD5E1;
  line-height: 1.65;
  margin-bottom: 12px;
}
.footer-social-links {
  display: flex;
  gap: 8px;
}
.footer-social-links a {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 14px;
}
.footer-col h4 {
  font-size: 14px;
  font-weight: 900;
  color: var(--nabd-gold);
  margin-bottom: 10px;
}
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.footer-links a {
  font-size: 12px;
  color: #CBD5E1;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 8px;
  font-size: 12px;
  color: #CBD5E1;
}
.footer-contact-item i {
  color: var(--nabd-gold);
  margin-top: 3px;
}
.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 14px;
  text-align: center;
  font-size: 11px;
  color: #94A3B8;
}

#nabd-toast {
  position: fixed;
  bottom: 80px;
  right: 50%;
  transform: translateX(50%);
  background: var(--nabd-navy-dark);
  color: #FFFFFF;
  border: 1px solid var(--nabd-gold);
  padding: 8px 18px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
  display: none;
  z-index: 100000;
  white-space: nowrap;
}

body.script:
window.onscroll = function() {
  var winScroll = document.body.scrollTop || document.documentElement.scrollTop;
  var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
  var scrolled = (winScroll / height) * 100;
  var pBar = document.getElementById('reading-progress');
  if (pBar) pBar.style.width = scrolled + '%';
};

function toggleMobileMenu() {
  var drawer = document.getElementById('mobileDrawer');
  var overlay = document.getElementById('drawerOverlay');
  if (drawer && overlay) {
    drawer.classList.toggle('open');
    overlay.classList.toggle('open');
  }
}

function copyPostUrl() {
  var url = window.location.href;
  if (navigator.clipboard) {
    navigator.clipboard.writeText(url).then(function() { showToast('تم نسخ رابط المقال بنجاح! 📋'); });
  }
}

function showToast(text) {
  var toast = document.getElementById('nabd-toast');
  if (toast) {
    toast.innerText = text;
    toast.style.display = 'block';
    setTimeout(function() { toast.style.display = 'none'; }, 3000);
  }
}
